// @ts-check
/** @typedef {import('../../InvocationContext.js').InvocationContext} InvocationContext */

import { Command } from '../../../utils/Command.js'
import { CommandType } from '../../../utils/CommandType.js'
import { RuntimeName } from '../../../utils/RuntimeName.js'
import { Duration, Uuid } from '../../../utils/DrawingTypes.js'
import { getCurrentCommandPayload } from './TypeParsingUtils.js'

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseDatetime(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    // Python naive datetimes have no timezone suffix; treat them as UTC
    const hasOffset = iso.endsWith('Z') || /[+-]\d{2}:\d{2}$/.test(iso)
    return new Date(hasOffset ? iso : iso + 'Z')
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {string}
 */
export function parseUUID(invocationContext) {
    return String(getCurrentCommandPayload(invocationContext)[1])
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {Date}
 */
export function parseTime(invocationContext) {
    const iso = String(getCurrentCommandPayload(invocationContext)[1])
    // Parse time-only ISO string (e.g. "HH:MM:SS.ffffff") on epoch day
    return new Date(`1970-01-01T${iso}Z`)
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {number} total milliseconds
 */
export function parseTimedelta(invocationContext) {
    const totalMicros = Number(getCurrentCommandPayload(invocationContext)[1])
    return totalMicros / 1_000
}

/**
 * @param {InvocationContext} invocationContext
 * @returns {URL}
 */
export function parseURL(invocationContext) {
    return new URL(String(getCurrentCommandPayload(invocationContext)[1]))
}

/** Inbound: Python result type string → JavaScript object */
export const PythonTypeParsingFunctions = new Map(
    /** @type {[string, (invocationContext: InvocationContext) => unknown][]} */ ([
        ['datetime.datetime', parseDatetime],
        ['uuid.UUID', parseUUID],
        ['datetime.time', parseTime],
        ['datetime.timedelta', parseTimedelta],
        ['URL', parseURL],
    ])
)

/** Outbound: JavaScript object → Command graph targeting the Python runtime */
export const PythonParsingArgument = new Map(
    /** @type {[Function, (value: any) => Command][]} */ ([
        [
            Date,
            (/** @type {Date} */ value) =>
                new Command(RuntimeName.Python, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Python, CommandType.GetType, ['datetime.datetime']),
                    'fromisoformat',
                    value.toISOString().replace('Z', '+00:00'),
                ]),
        ],
        [
            URL,
            (/** @type {URL} */ value) =>
                new Command(RuntimeName.Python, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Python, CommandType.GetType, ['urllib.parse']),
                    'urlparse',
                    value.href,
                ]),
        ],
        [
            Duration,
            (/** @type {Duration} */ value) => {
                const totalMicros = value.milliseconds * 1000
                const seconds = Math.trunc(totalMicros / 1_000_000)
                const microseconds = totalMicros % 1_000_000
                return new Command(RuntimeName.Python, CommandType.CreateClassInstance, [
                    new Command(RuntimeName.Python, CommandType.GetType, ['datetime.timedelta']),
                    0,
                    seconds,
                    microseconds,
                ])
            },
        ],
        [
            Uuid,
            (/** @type {Uuid} */ value) =>
                new Command(RuntimeName.Python, CommandType.InvokeStaticMethod, [
                    new Command(RuntimeName.Python, CommandType.GetType, ['uuid']),
                    'UUID',
                    value.value,
                ]),
        ],
    ])
)
